// node run_fs_recon.js - FinCom's balance sheet matched with the audited one (owner, 29-Oct-2026: "match the figures
// uploaded by the last year balance sheet and generated by FinCom, identify the difference and make it correct as per
// balance uploaded"). On the made-up books of tests/fixtures/fin-statements (2025-26) and a made-up audited balance sheet as
// at 31-Mar-2026 (fixtures/fin-statements/audited-bs-2026.json) that differs on purpose:
//   (i)   Willow Labs (90,000, a debtor in the books) shown as a loan to a related party  -> a mapping change;
//   (ii)  the provision for income tax (6,83,940) and 25,000 more depreciation on computers -> two adjustments dated
//         31-Mar-2026 (FinCom's own list, never posted to Tally);
//   (iii) 1,000 more trade payables, 1,000 less reserves                                    -> listed, never forced.
// FinRecon (src/js/88-fin-recon.js): the comparison head by head and note line by note line; the proposals in order
// (mapping, adjustments, the profit they explain); accept / reject / undo, each recorded; the accepted 31-March entries
// carried into 2026-27's opening balances (until they are passed in Tally); the journal rows for Tally.
const {load, HTML} = require("./harness"), fs = require("fs"), path = require("path");
const NAMES = ["num", "r2", "xesc", "esc", "MONTHS", "fmtDate", "tallyDate", "STATE_CODES", "RULE_DEFAULTS", "Books", "LedMaster", "Audit", "MIS", "FS", "FinSt", "FinPyBs", "FinRecon", "INR"];
const {ctx, x} = load(HTML, NAMES);
let fails = 0; const ok = (c, w) => { console.log((c ? "  ok   " : "  FAIL ") + w); if (!c) fails++; };
const eq = (a, b, w) => ok(Math.abs((a == null ? NaN : a) - b) < 1e-6, w + ": " + a + (Math.abs((a == null ? NaN : a) - b) < 1e-6 ? "" : " (expected " + b + ")"));
const FIX = path.join(__dirname, "fixtures", "fin-statements"), read = f => JSON.parse(fs.readFileSync(path.join(FIX, f), "utf8"));
const C = read("company.json"), AUD = read("audited-bs-2026.json");
const r2 = v => Math.round(v * 100) / 100, shift = end => String(Number(end.slice(0, 4)) - 1) + end.slice(4);
// the books (as tests/run_fin_statements.js), the copy reaching to 31-Mar-2027 with one entry in 2026-27
function books(){
  const under = Object.assign({}, C.groups), led = {};
  Object.entries(C.o).forEach(([n, v]) => { led[n] = {open: -v, close: 0, parent: under[n]}; });
  const vouchers = [], bank = "Northbank Current A/c";
  C.additions.forEach(([l, d, a], i) => vouchers.push({id: "a" + i, date: d, type: "Journal", narr: "Purchase of " + l, ent: [{l, a: -a}, {l: bank, a}]}));
  [["20250331", C.p, C.plp, C.o], ["20260331", C.c, C.plc, C.p]].forEach(([end, bs, pl, prev]) => { const ent = [];
    Object.keys(bs).forEach(n => { if (n === bank) return; const added = C.additions.filter(([l, d]) => l === n && d <= end && d > shift(end)).reduce((s, z) => s + z[2], 0);
      const mv = r2((bs[n] || 0) - (prev[n] || 0) - added); if (mv) ent.push({l: n, a: -mv}); });
    Object.entries(pl).forEach(([n, v]) => { if (v) ent.push({l: n, a: -v}); });
    ent.push({l: bank, a: r2(-ent.reduce((s, e) => s + e.a, 0))}); vouchers.push({id: "m" + end, date: end, type: "Journal", narr: "Movements (fixture)", ent}); });
  vouchers.push({id: "n1", date: "20260630", type: "Sales", narr: "Services, April-June 2026", ent: [{l: "Software Services - Export", a: 500000}, {l: bank, a: -500000}]});
  return {under, groups: {}, ledInfo: {}, vouchers, meta: {from: "20240401"}, tb: {from: "20240401", to: "20270331", at: "2027-04-30T10:00:00Z", src: "copy", led},
    msme: {"Bluebell Print Works": "Micro"}, fs: {taxDep: {"2024": {c40: 220000, pm15: 140000, f10: 80000}}}};
}
ctx.S.firm = {firmName: "Made-up & Associates", frn: "000000S", partner: "A. Sample", mno: "000001", place: "Bengaluru"};
ctx.CO = () => ({name: "Larkspur Analytics Private Limited", pan: "AABCL1234F", cin: "U72900KA2015PTC000001"});
const b = books(); ctx.S.books = b;
const FinSt = x.FinSt, PB = x.FinPyBs, FR = x.FinRecon;

try {
  ok(FR && typeof FR.compare === "function" && typeof FR.propose === "function", "FinRecon is in the program (src/js/88-fin-recon.js)");
  const before = JSON.stringify(FinSt.build("2025", {unit: 1, dec: 2}).bs);
  ok(FR.compare("2025").none === true, "no audited balance sheet for 31-Mar-2026 yet: nothing to match, said so");
  // the audited balance sheet for 2025-26: kept as last year's balance sheet of 2026-27 (one store for both)
  const rd = PB.prepare(PB.fromRows([{name: "Balance Sheet", rows: [[AUD.title], [AUD.what], [AUD.unit], AUD.head].concat(AUD.rows)}]), "co");
  PB.save("2026", Object.assign(rd, {file: "Larkspur audited BS 2025-26.xlsx", size: 1000, sha256: "cd".repeat(32)}), {by: "test"});
  ok(JSON.stringify(FinSt.build("2025", {unit: 1, dec: 2}).bs) === before, "uploading it changes none of 2025-26's figures by itself");

  console.log("\nThe comparison, as at 31-Mar-2026");
  const cmp = FR.compare("2025"), H = id => cmp.heads.find(z => z.id === id) || {};
  ok(cmp.asAt === "31-Mar-2026" && cmp.v === 1 && cmp.file === "Larkspur audited BS 2025-26.xlsx", "for the year's end, from the upload (" + cmp.asAt + ", v" + cmp.v + ")");
  eq(H("tr").aud, 3100000.75, "trade receivables audited"); eq(H("tr").fin, 3190000.75, "... FinCom"); eq(H("tr").diff, -90000, "... difference");
  eq(H("stla").diff, 90000, "short-term loans and advances +90,000"); eq(H("ocl").diff, 683940, "other current liabilities +6,83,940");
  eq(H("ppe").diff, -25000, "property, plant and equipment -25,000"); eq(H("tpo").diff, 1000, "trade payables (others) +1,000");
  eq(H("rs").aud, 6432160.05, "reserves audited"); eq(H("rs").fin, 7142100.05, "... FinCom (with this year's profit)"); eq(H("rs").diff, -709940, "... difference");
  ok(cmp.bad === 6 && ["sc", "ltp", "tpm", "stp", "dta", "ltla", "cash", "oca"].every(id => H(id).diff === 0), "six heads differ, the rest agree (" + cmp.heads.filter(z => z.diff).map(z => z.id).join(", ") + ")");
  const cd = (h, k) => (H(h).codes || []).find(z => z.key === k) || {};
  eq(cd("ocl", "7D").diff, 683940, "note line by note line: provision for income tax 6,83,940"); eq(cd("ocl", "7B").diff, 0, "... employee payables agree");
  eq(cd("ppe", "8A").diff, -25000, "... computers (net block) -25,000"); eq(cd("stla", "12H").diff, 90000, "... loans to related parties +90,000");
  ok((cd("tr", "10A").ledgers || []).some(l => l.ledger === "Willow Labs" && l.final === 90000), "each FinCom figure opens to its ledgers (receivables: Willow Labs 90,000)");

  console.log("\nThe proposals");
  let p = FR.propose("2025");
  ok(p.mapping.length === 1 && p.mapping[0].ledger === "Willow Labs" && p.mapping[0].from === "10A" && p.mapping[0].to === "12H" && /Loans and advances to related parties/.test(p.mapping[0].why),
    "(a) a mapping change: " + p.mapping.map(m => m.ledger + " " + m.from + " -> " + m.to + " (" + m.why + ")").join("; "));
  const tax = p.adjustments.find(a => a.kind === "tax") || {}, dep = p.adjustments.find(a => a.kind === "dep") || {};
  ok(tax.dr === "Income Tax - Current Year" && tax.cr === "Provision for Income Tax FY 2025-26" && tax.amt === 683940 && tax.narr === "To match audited balance sheet: Other current liabilities (provision for income tax)" && tax.date === "20260331",
    "(b) the provision for tax: Dr " + tax.dr + " / Cr " + tax.cr + " " + tax.amt + " on " + tax.date + ": " + tax.narr);
  ok(dep.dr === "Depreciation" && dep.cr === "Accumulated Depreciation - Computers" && dep.amt === 25000 && /Property, plant and equipment/.test(dep.narr), "(b) depreciation: Dr " + dep.dr + " / Cr " + dep.cr + " " + dep.amt);
  ok(p.adjustments.length === 2, "two adjustments, nothing else invented (" + p.adjustments.map(a => a.kind).join(", ") + ")");
  ok(p.profit.diff === -709940 && p.profit.explained === -708940 && p.profit.left === -1000, "(c) the profit: reserves differ by -7,09,940; the adjustments explain -7,08,940; -1,000 left (" + JSON.stringify(p.profit) + ")");
  ok(p.left.length === 2 && p.left.some(z => z.id === "tpo" && z.diff === 1000) && p.left.some(z => z.id === "rs" && z.diff === -1000), "what nothing explains stays listed: " + p.left.map(z => z.id + " " + z.diff).join(", "));

  console.log("\nApproving: reject, accept, undo, each recorded");
  FR.reject("2025", p.mapping[0].id, {by: "Owner"});
  ok(FR.propose("2025").mapping.length === 0 && FR.propose("2025").rejected.length === 1, "a rejected proposal leaves the list, kept as rejected");
  const rlog = FR.log("2025").find(z => z.kind === "reject");
  FR.undo("2025", rlog.id, {by: "Owner"});
  ok(FR.propose("2025").mapping.length === 1, "... and can be taken back");
  FR.acceptAll("2025", "map", {by: "Owner"});
  ok(b.fs.map["Willow Labs"] === "12H", "accept all mapping changes: Willow Labs -> 12H, by hand");
  FR.acceptAll("2025", "adj", {by: "Owner"});
  const adj = b.fs.adj["2025"] || [];
  ok(adj.length === 2 && adj.every(a => a.recon && a.carry && a.date === "20260331" && a.by === "Owner" && a.at) && b.fs.map["Provision for Income Tax FY 2025-26"] === "7D", "accept all adjustments: two entries in FinCom's list, dated 31-Mar-2026, by whom and when; the new ledger coded 7D");
  const lg = FR.log("2025").filter(z => z.kind === "accept");
  ok(lg.length === 3 && lg.every(z => z.by === "Owner" && z.at), "each accepted change recorded (" + lg.length + ")");
  let c2 = FR.compare("2025");
  ok(c2.bad === 2 && c2.heads.find(z => z.id === "tpo").diff === 1000 && c2.heads.find(z => z.id === "rs").diff === -1000, "recomputed: only the unexplained 1,000 left (" + c2.heads.filter(z => z.diff).map(z => z.id + " " + z.diff).join(", ") + ")");
  p = FR.propose("2025");
  ok(!p.mapping.length && !p.adjustments.length && p.left.length === 2 && p.profit.left === -1000, "no proposal left; what is left is said");
  const d25 = FinSt.build("2025", {unit: 1, dec: 2});
  ok(d25.checks.every(c => c.value === 0), "2025-26's checks still read 0 " + d25.checks.filter(c => c.value).map(c => c.key + " " + c.value).join("; "));
  eq(d25.bs.total.assets.cy, 8562800.55, "FinCom's balance sheet total = the audited 85,62,800.55");
  const depLog = lg.find(z => /Depreciation/.test(z.what));
  FR.undo("2025", depLog.id, {by: "Owner"});
  ok(FR.compare("2025").heads.find(z => z.id === "ppe").diff === -25000 && (b.fs.adj["2025"] || []).length === 1, "an accepted change undone: the depreciation entry gone, the difference back");
  FR.accept("2025", FR.propose("2025").adjustments[0].id, {by: "Owner"});
  ok(FR.compare("2025").bad === 2, "accepted again");

  console.log("\nCarried into 2026-27's opening balances");
  const h1 = FinSt.build("2026", {unit: 1, dec: 2, period: {preset: "h1", cmp: "fy"}});
  ok(!h1.error && h1.tb.carried && h1.tb.carried.n === 2 && h1.tb.carried.note === "Opening balances adjusted to the audited balance sheet (2 entries)", "2026-27: " + (h1.tb.carried && h1.tb.carried.note));
  eq(h1.bs.total.assets.py, 8562800.55, "the comparative balance sheet as at 31-Mar-2026: the audited total");
  const ln = (dd, k, code) => ((dd.notes.find(n => n.key === k) || {lines: []}).lines.find(l => l.code === code) || {});
  eq(ln(h1, "7", "7D").cy, 683940, "the provision for tax is in the opening, so in the balance sheet as on 30-Sep-2026");
  eq(ln(h1, "4", "4A").cy, 6433160.05, "the surplus starts from the adjusted closing (the audited, but for the 1,000 nothing explains)");
  ok(h1.checks.every(c => c.value === 0) && h1.bs.total.eqL.cy === h1.bs.total.assets.cy, "2026-27's H1 ties, checks 0 " + h1.checks.filter(c => c.value).map(c => c.key + " " + c.value).join("; "));
  const fy26 = FinSt.build("2026", {unit: 1, dec: 2});
  eq(fy26.bs.total.assets.py, 8562800.55, "the full year 2026-27's PY: the entries counted once");
  FR.setInTally("2025", true, {by: "Owner"});
  const h1b = FinSt.build("2026", {unit: 1, dec: 2, period: {preset: "h1", cmp: "fy"}});
  ok(!h1b.tb.carried || h1b.tb.carried.n === 0, "passed in Tally: no longer carried (Tally's own balances now hold them)");
  FR.setInTally("2025", false, {by: "Owner"});

  console.log("\nJournal entries for Tally");
  const j = FR.journal("2025");
  ok(j.length === 2 && j.every(r => r.date === "31-Mar-2026" && r.type === "Journal" && r.dr && r.cr && r.amt > 0 && /^To match audited balance sheet/.test(r.narr)), "two journal entries dated 31-Mar-2026: " + j.map(r => r.dr + " / " + r.cr + " " + r.amt).join("; "));
} catch (e){ console.error(e); fails++; }
console.log("\n" + (fails ? fails + " FAILED" : "all passed")); process.exit(fails ? 1 : 0);
